    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "A high proportion of SARS-CoV-2 patients survive infection but the prevalence of chronic sequelae and resulting disability is increasing. These survivors need clinical management and rehabilitation to facilitate good health outcomes.",
      "reason": "The rationale section describes the current state of knowledge (high proportion of survivors with chronic sequelae) and uncertainties (need for clinical management and rehabilitation)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "The best available research evidence is required to inform management and rehabilitation decisions, interventions, and health systems for COVID-19 survivors with adverse clinical sequelae. Further evidence is warranted to estimate the resources needed to plan for setting appropriate and adequately delivered post-acute and long-term rehabilitation services.",
      "reason": "The rationale section explains the importance and need for the review by stating that best available evidence is required to inform decisions and that further evidence is warranted to estimate resources."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "This rapid living systematic review on rehabilitation and COVID-19 was initiated in April 2020 as a component of the Cochrane Rehabilitation REH-COVER action. 3 Since its inception, it has been updated monthly, with the most recent update leading to a total of 319 papers up to April 30 th , 2021.",
      "reason": "The rationale section identifies the previous review (initiated in April 2020, updated monthly) and explains the need for the current review (recent increase in analytical studies encouraged advancing methodology)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": "text_4",
      "quote": null,
      "reason": "The rationale section does not describe the proposed mechanism of action of the rehabilitation interventions, which is required for reviews of intervention effects."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": "text_4",
      "quote": null,
      "reason": "The rationale section does not mention considering a logic model to show hypothesised relationships between intervention components and outcomes, which is required for complex interventions."
    }
  ],
  "confidence": 90
}

